122	function resolveSuggestionOptions(
123	  cmdObj: Partial<CommandLineOptions & Command>,
124	  commandLineOptions: Record<string, any> | undefined,
125	  evaluateOptions: InternalEvaluateOptions,
126	): Pick<InternalEvaluateOptions, 'generateSuggestions' | 'suggestionsCount'> {
127	  const { suggestPrompts } = cmdObj as EvalCommandOptions;
128	
129	  // --suggest-prompts is itself an enable signal — passing a count opts in even
130	  // if some other source explicitly set generateSuggestions=false.
131	  if (suggestPrompts !== undefined) {
132	    return { generateSuggestions: true, suggestionsCount: suggestPrompts };
133	  }
134	
135	  const explicitGenerate =
136	    cmdObj.generateSuggestions ??
137	    commandLineOptions?.generateSuggestions ??
138	    evaluateOptions.generateSuggestions;
139	
140	  if (explicitGenerate !== true) {
141	    // Return explicit false so Object.assign clears any truthy default already on options.
142	    return explicitGenerate === false ? { generateSuggestions: false } : {};
143	  }
144	
145	  // Read cmdObj.suggestionsCount too: doEval is exported and non-Commander
146	  // callers may pass the canonical key directly instead of the suggestPrompts CLI alias.
147	  const suggestionsCount =
148	    cmdObj.suggestionsCount ??
149	    commandLineOptions?.suggestionsCount ??
150	    evaluateOptions.suggestionsCount;
151	  return suggestionsCount === undefined
152	    ? { generateSuggestions: true }
153	    : { generateSuggestions: true, suggestionsCount };
154	}
